#!/usr/bin/env python3
"""只给固定上游commit应用受控iOS候选补丁；此工具不授予离线发布资格。"""
import argparse
import difflib
import hashlib
import importlib.util
import json
import pathlib
import subprocess

TAG = 'libreoffice-26.2.6.3'
COMMIT = '8221e31b3ac356a1623c672912a3d2b492f7e3d1'
ROOT = pathlib.Path(__file__).resolve().parent
RECEIPT = '.office-pdf-offline-policy.json'


def digest(value):
    return hashlib.sha256(value).hexdigest()


def git(source, *args):
    return subprocess.check_output(['git', '-C', str(source), *args])


def load_policy():
    raw = (ROOT / 'offline-policy.json').read_bytes()
    policy = json.loads(raw)
    if policy['schema'] != 1 or policy['policyId'] != 'lizhao-office-pdf-ios-offline-candidate-v1' or \
            (policy['sourceTag'], policy['sourceCommit'], policy['qualified']) != (TAG, COMMIT, False):
        raise ValueError('候选策略身份或资格状态不匹配')
    paths = [entry['path'] for entry in policy['files']]
    if not paths or len(paths) != len(set(paths)):
        raise ValueError('策略文件清单为空或重复')
    policy['policySha256'] = digest(raw)
    return policy


def transform(original, entry):
    if digest(original) != entry['beforeSha256']:
        raise ValueError('上游文件SHA-256漂移: ' + entry['path'])
    value = original.decode('utf-8')
    for replacement in entry['replacements']:
        before = replacement['before']
        if not before or value.count(before) != 1:
            raise ValueError('补丁锚点不唯一: ' + entry['path'])
        value = value.replace(before, replacement['after'], 1)
    result = value.encode('utf-8')
    if digest(result) != entry['afterSha256']:
        raise ValueError('补丁结果SHA-256不匹配: ' + entry['path'])
    return result


def expected_receipt(policy):
    return {key: policy[key] for key in ('policyId', 'policySha256', 'sourceTag', 'sourceCommit', 'qualified')}


def prepare_files(source, policy, original_reader):
    """写前校验全部文件，拒绝混合应用、用户改动、符号链接和路径越界。"""
    prepared = []
    states = set()
    for entry in policy['files']:
        relative = pathlib.PurePosixPath(entry['path'])
        if relative.is_absolute() or '..' in relative.parts or '\\' in entry['path']:
            raise ValueError('补丁路径越界')
        target = source.joinpath(*relative.parts)
        if target.is_symlink() or target.resolve() != source.joinpath(*relative.parts):
            raise ValueError('补丁路径含符号链接: ' + entry['path'])
        original = original_reader(entry['path'])
        changed = transform(original, entry)
        current = target.read_bytes()
        if current == original:
            states.add('original')
        elif current == changed:
            states.add('applied')
        else:
            raise ValueError('拒绝覆盖非策略改动: ' + entry['path'])
        prepared.append((target, original, changed))
    if len(states) != 1:
        raise ValueError('补丁部分应用；拒绝自动覆盖或补齐')
    return prepared, states.pop()


def verify_source_identity(source, policy):
    if git(source, 'rev-parse', 'HEAD').decode().strip() != COMMIT:
        raise ValueError('上游HEAD不是固定commit')
    if git(source, 'rev-parse', TAG + '^{commit}').decode().strip() != COMMIT:
        raise ValueError('上游tag不是固定commit')
    if git(source, 'diff', '--cached', '--name-only').strip():
        raise ValueError('上游存在暂存改动；拒绝混入构建')
    changed = set(git(source, 'diff', '--name-only', 'HEAD').decode().splitlines())
    extra = changed - {entry['path'] for entry in policy['files']}
    if extra:
        spec = importlib.util.spec_from_file_location('office_pdf_build_compat', ROOT / 'build_compat.py')
        compatibility = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(compatibility)
        if extra != {entry['path'] for entry in compatibility.patches()}:
            raise ValueError('上游存在策略之外的受跟踪改动')
        # 单独的七文件构建兼容身份；完整清单、精确结果SHA及回执须全部匹配。
        compatibility.verify(source)


def apply_or_verify(source, check=False):
    source = source.resolve(strict=True)
    policy = load_policy()
    verify_source_identity(source, policy)
    prepared, state = prepare_files(source, policy, lambda name: git(source, 'show', 'HEAD:' + name))
    review_patch = []
    for entry, (_, original, changed) in zip(policy['files'], prepared):
        review_patch.extend(difflib.unified_diff(original.decode('utf-8').splitlines(True),
                            changed.decode('utf-8').splitlines(True),
                            fromfile='a/' + entry['path'], tofile='b/' + entry['path']))
    if ''.join(review_patch).encode('utf-8') != (ROOT / 'offline-policy.patch').read_bytes():
        raise ValueError('审阅patch与精确替换策略不一致')
    receipt = source / RECEIPT
    expected = expected_receipt(policy)
    if state == 'applied':
        if receipt.is_symlink() or not receipt.is_file() or json.loads(receipt.read_bytes()) != expected:
            raise ValueError('已修改源码缺少匹配的策略回执')
    elif check:
        raise ValueError('必须先应用候选离线补丁再构建')
    else:
        if receipt.exists() or receipt.is_symlink():
            raise ValueError('原始源码中已有策略回执，拒绝覆盖')
        written = []
        receipt_created = False
        try:
            for target, original, changed in prepared:
                target.write_bytes(changed)
                written.append((target, original))
            with receipt.open('x', encoding='utf-8', newline='\n') as stream:
                receipt_created = True
                json.dump(expected, stream, ensure_ascii=False, indent=2)
                stream.write('\n')
        except OSError:
            # 只撤销本次刚写入的受控文件；不操作其它上游内容。
            for target, original in reversed(written):
                target.write_bytes(original)
            if receipt_created:
                receipt.unlink(missing_ok=True)
            raise
    return expected


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--source', required=True, type=pathlib.Path)
    parser.add_argument('--check', action='store_true', help='只核对已应用补丁，不修改源码')
    args = parser.parse_args()
    try:
        result = apply_or_verify(args.source, args.check)
    except (OSError, ValueError, KeyError, subprocess.SubprocessError) as error:
        parser.exit(1, '离线候选策略失败: ' + str(error) + '\n')
    print(json.dumps(result, ensure_ascii=False, indent=2))


if __name__ == '__main__':
    main()

#!/usr/bin/env python3
"""在Mac上核验并重建同tag iOS LO，再封装真实内核。Python标准库。"""
import argparse
import collections
import hashlib
import importlib.util
import json
import mmap
import os
import pathlib
import re
import shlex
import shutil
import subprocess
import stat
import struct
import sys
import tempfile

TAG = 'libreoffice-26.2.6.3'
# 2026-10-22官方git ls-remote解析的annotated tag目标；不信任本地同名可移动tag。
COMMIT = '8221e31b3ac356a1623c672912a3d2b492f7e3d1'
ROOT = pathlib.Path(__file__).resolve().parent
MIN_IOS = '14.5'
SYMBOL_KINDS = ('strong', 'weak', 'common', 'undefined', 'weakUndefined')
# 单对象、整个闭包及最终aggregate独立有界，不改变CI的4GiB候选缓存预算。
MAX_LINK_INPUT = 512 * 1024**2
MAX_LINK_TOTAL = 4 * 1024**3
MAX_LINK_MEMBERS = 100000
MAX_AUDIT_BYTES = 8 * 1024**2
# map原文单独允许1GiB；不扩大AUDIT或其他普通证据的限额。
MAX_LINK_MAP = 1024**3
# 固定ICU78官方little-endian完整数据；一致但被替换的dummy数据也不能放行。
ICU_DATA_IDENTITY = (33107232, 'd5cf2a40dccbe471781ec7af85693bff542ff12f0b670c9630c4e72d60714b8b')
# 固定上游与实际生效的静态分派/补丁身份；不从旧SW receipt读取生产资格。
LINK_SOURCE_SHA256 = (
    ('source','cppu/source/uno/lbenv.cxx','136bc429309688898416232557083694aa7355cf91c676ab984a1ada2fc48405'),
    ('source','cppu/source/uno/lbmap.cxx','86025c3b5cb60d4aa9c96a73c8b45780425780ab15439cbf63688c2bc93955d2'),
    ('source','bridges/source/cpp_uno/shared/component.cxx','6e77d7180a34b85414dab5159709b99ebfb996c6ad52263e2e5f3a9b52f26be1'),
    ('source','desktop/source/lib/init.cxx','3263d8c8aeeb37b1c5a3131684ecf6c2617d508878e44bdb026a8e291be691ae'),
    ('source','external/nss/nss-ios.patch','8599bf3e918715449dd185f450f96e56bdaf04a344e59f257a9080548f1ec9c5'),
    ('build','workdir/UnpackedTarball/nss/nss/lib/freebl/loader.c','48544934911aa7cb7641c55fc76cf3675bd8b5b74153c1e794a26f565deb7f76'),
    ('build','workdir/UnpackedTarball/nss/nss/lib/freebl/config.mk','cbc4502fcfd1ed4fe584afcfb73ec35ea73579f8e1454db0edf1ed0074263d27'),
    ('build','workdir/UnpackedTarball/nss/nss/lib/freebl/Makefile','f3c3200d1cf77dd6e7d9bfa8d0ffd5fa9c0e8705b674a002f221d9b173c1550c'),
    ('build','workdir/UnpackedTarball/nss/nss/lib/softoken/pkcs11.c','2aeb1807001d3c2a140947bfb60925c6fdb41be5cdcf8e63c65988f6ef2e1eab'))


def link_parser():
    # 只复用纯ar/Mach-O函数；不得使用SW恢复/receipt/缺失容忍入口。
    spec = importlib.util.spec_from_file_location('office_pdf_pure_link_parser', ROOT / 'ci/inspect_link.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


class MappedArchive:
    """只读mmap的bytes接口；ar解析器逐成员复制，避免整库重复驻留。"""
    def __init__(self, mapping):
        self.mapping = mapping

    def __len__(self):
        return len(self.mapping)

    def __getitem__(self, key):
        return self.mapping[key]

    def startswith(self, prefix):
        return self.mapping[:len(prefix)] == prefix


def native_members(path, max_bytes=MAX_LINK_INPUT):
    parser = link_parser()
    if path.is_symlink() or not path.is_file() or not 0 < path.stat().st_size <= max_bytes:
        raise ValueError('原生输入缺失/链接/体积超限: ' + str(path))
    with path.open('rb') as stream, mmap.mmap(stream.fileno(), 0, access=mmap.ACCESS_READ) as mapping:
        data = MappedArchive(mapping)
        if data.startswith(b'!<arch>\n'):
            yield from parser.archive_members(data, max_bytes=max_bytes, max_members=MAX_LINK_MEMBERS)
        else:
            raw = mapping[:]
            yield {'index': 1, 'occurrence': 1, 'name': path.name, 'bytes': len(raw),
                   'sha256': hashlib.sha256(raw).hexdigest(), 'data': raw}


def scan_link_inputs(inputs, build):
    parser, rows, total, count = link_parser(), [], 0, 0
    if len(inputs) > 2000 or len(inputs) != len(set(inputs)):
        raise ValueError('原生输入数超限或存在物理重复路径')
    for path in inputs:
        total += path.stat().st_size
        if total > MAX_LINK_TOTAL:
            raise ValueError('完整静态输入总字节超限')
        before = sha256(path)
        row = {'path': str(path), 'bytes': path.stat().st_size, 'sha256': before, 'members': []}
        for member in native_members(path):
            symbols = parser.macho_symbols(member['data'])
            row['members'].append({**{k:v for k,v in member.items() if k != 'data'}, 'symbols': symbols})
            count += 1
            if count > MAX_LINK_MEMBERS:
                raise ValueError('完整静态成员数超限')
        if not row['members']:
            raise ValueError('空archive无法证明arm64输入: ' + str(path))
        if sha256(path) != before:
            raise ValueError('扫描期间输入身份变化: ' + str(path))
        rows.append(row)
    return rows


def member_counter(rows):
    return collections.Counter((m['bytes'], m['sha256']) for row in rows for m in row['members'])


def symbol_union(rows, kind):
    return {s for row in rows for member in row['members'] for s in member['symbols'][kind]}


def normalize_ios_link_inputs(inputs, build, rows):
    """仅精确路径候选排除，所有业务依赖由联合after图再次证明。"""
    unpacked = 'workdir/UnpackedTarball/'
    pairs = [('curl', 'curl/lib/.libs/libcurlu.a', 'curl/lib/.libs/libcurl.a')]
    pairs += [(name, f'{folder}/src/lib/.libs/{internal}', f'{folder}/src/lib/.libs/{public}') for name,folder,internal,public in (
        ('cdr','libcdr','libcdr-internal.a','libcdr-0.1.a'),
        ('visio','libvisio','libvisio-internal.a','libvisio-0.1.a'),
        ('epubgen','libepubgen','libepubgen_internal.a','libepubgen-0.1.a'))]
    pairs += [('sharpyuv-' + cpu, 'libwebp/sharpyuv/.libs/libsharpyuv_' + cpu + '.a',
               'libwebp/sharpyuv/.libs/libsharpyuv.a') for cpu in ('neon','sse2')]
    by_path = {pathlib.Path(row['path']): row for row in rows}
    removed, rules = set(), []
    for name, old, canonical in pairs:
        old, canonical = build / (unpacked + old), build / (unpacked + canonical)
        if old not in inputs:
            continue
        if canonical not in inputs:
            raise ValueError('缺少canonical正式库: ' + str(canonical))
        if name == 'curl':
            if not symbol_union([by_path[canonical]], 'strong') <= symbol_union([by_path[old]], 'strong'):
                raise ValueError('curl UNITTESTS副本未覆盖正式库强定义')
        elif member_counter([by_path[old]]) - member_counter([by_path[canonical]]):
            raise ValueError('便利库成员多重集未被canonical包含: ' + name)
        removed.add(old)
        rules.append({'family': name, 'excluded': str(old.relative_to(build)),
                      'canonical': str(canonical.relative_to(build)), 'memberContainment': name != 'curl'})
    for family, relatives in (
            ('nss', [unpacked + 'nss/nss/lib/freebl/out/libfreebl.a']),
            ('uno', ['instdir/program/libnet_uno.a','instdir/program/libunsafe_uno_uno.a']),
            ('icu', [unpacked + 'icu/source/lib/libicudata.a'])):
        for relative in relatives:
            path = build / relative
            if path in inputs:
                removed.add(path)
                rules.append({'family': family, 'excluded': relative, 'requiresFinalContract': True})
    return [p for p in inputs if p not in removed], rules


def symbol_summary(values):
    ordered = sorted(values)
    return {'count': len(ordered), 'sha256': hashlib.sha256(json.dumps(ordered, separators=(',', ':'), ensure_ascii=False).encode()).hexdigest()}


def file_identity(path, root):
    if path.is_symlink() or not path.resolve().is_relative_to(root.resolve()) or not path.is_file() or path.stat().st_size>MAX_LINK_INPUT:
        raise ValueError('必要文件缺失/路径逃逸: ' + str(path))
    return {'path':str(path),'bytes':path.stat().st_size,'sha256':sha256(path)}


def validate_link_profile(source, build):
    text=(build/'config_host.mk').read_text(encoding='utf-8')
    expected={'OS':'iOS','CPUNAME':'AARCH64','CPPU_ENV':'gcc3','DISABLE_DYNLOADING':'TRUE','ENABLE_DOTNET':'TRUE'}
    for key,value in expected.items():
        matches=re.findall(r'^(?:export\s+)?'+key+r'\s*(?::?=)\s*([^\n]*)$',text,re.MULTILINE)
        if matches != [value]:
            raise ValueError('最终链接profile配置不匹配: '+key)
    files=[file_identity(build/'config_host.mk',build)]
    for origin,relative,wanted in LINK_SOURCE_SHA256:
        root=source if origin=='source' else build
        entry=file_identity(root/relative,root)
        if entry['sha256']!=wanted:
            raise ValueError('静态分派/ICU/NSS固定源码身份变化: '+relative)
        files.append(entry)
    return {'values':expected,'files':files}


def validate_ios_families(rows, selected, build, resources):
    """完整make后对NSS后端、UNO静态分派及ICU外部数据分别闭环。"""
    by_path={pathlib.Path(row['path']):row for row in rows}
    selected=set(selected)
    def require(relative, retained=True):
        path=build/relative
        if path not in by_path or (retained and path not in selected):
            raise ValueError('必要final输入缺失或被排除: '+relative)
        return by_path[path]
    prefix='workdir/UnpackedTarball/'
    for folder,public,internal in (
            ('curl/lib','libcurl.a','libcurlu.a'),('libcdr/src/lib','libcdr-0.1.a','libcdr-internal.a'),
            ('libvisio/src/lib','libvisio-0.1.a','libvisio-internal.a'),
            ('libepubgen/src/lib','libepubgen-0.1.a','libepubgen_internal.a'),
            ('libwebp/sharpyuv','libsharpyuv.a','libsharpyuv_neon.a'),
            ('libwebp/sharpyuv','libsharpyuv.a','libsharpyuv_sse2.a')):
        require(prefix+folder+'/.libs/'+public)
        require(prefix+folder+'/.libs/'+internal,False)
    nss=prefix+'nss/nss/lib/freebl/out/'
    parent=require(nss+'libfreebl.a',False)
    child_dir=build/(nss+'Darwin_SINGLE_SHLIB')
    # 只列两个已知后端目录，不扫整个构建树；目录中的实际root/deprecated对象全部保留。
    child_paths=sorted(child_dir.glob('*.o'))+sorted((child_dir/'deprecated').glob('*.o'))
    if not child_paths or len(child_paths)>1000:
        raise ValueError('NSS真实后端对象缺失/超限')
    for path in child_paths:
        file_identity(path,build)
        if path not in selected:
            raise ValueError('NSS raw root/deprecated对象遗漏: '+str(path))
    for name in ('deprecated/alg2268.o','deprecated/seed.o'):
        require(nss+'Darwin_SINGLE_SHLIB/'+name)
    paired=[]
    if len(parent['members'])!=13 or sum(m['name']=='loader.o' for m in parent['members'])!=1:
        raise ValueError('NSS父archive不再是loader+十二libcrux对象')
    for member in parent['members']:
        if member['name']=='loader.o':continue
        child=require(nss+'Darwin_SINGLE_SHLIB/'+member['name'])
        if member_counter([{'members':[member]}]) != member_counter([child]):
            raise ValueError('NSS libcrux父/child成员bytes/SHA不一致')
        paired.append({'parentIndex':member['index'],'child':child['path'],'sha256':member['sha256']})
    nss_rows=[row for row in rows if pathlib.Path(row['path']).is_relative_to(child_dir) and pathlib.Path(row['path']) in selected]
    nss_strong=symbol_union(nss_rows,'strong')
    lifecycle={'_BL_Cleanup','_BL_SetForkState','_RNG_RNGShutdown','_FREEBL_GetVector','_DH_NewKey','_DH_Derive'}
    if not lifecycle <= nss_strong:
        raise ValueError('NSS真实生命周期/算法强定义遗漏: '+repr(sorted(lifecycle-nss_strong)))
    for bits in ('128','192','256'):
        for direction in ('enc','dec'):
            row=require(nss+'Darwin_SINGLE_SHLIB/aarch64-gcm-slothy/gcm-'+bits+'-'+direction+'.o')
            name='_aes_gcm_'+direction+'_kernel_slothy_base_'+bits
            if name not in symbol_union([row],'strong'):
                raise ValueError('NSS slothy真实算法入口遗漏: '+name)
    bridge=require('instdir/program/libgcc3_uno.a')
    for name in ('libnet_uno.a','libunsafe_uno_uno.a'):require('instdir/program/'+name,False)
    # 固定component宏使用完整字面token；CPPU_ENV=gcc3决定库名，不展开标识符内部前缀。
    entries={'lbenv':'_CPPU_ENV_uno_initEnvironment','lbmap':'_CPPU_ENV_uno_ext_getMapping'}
    cpp_rows=[]
    for file,symbol in entries.items():
        path=build/('workdir/CxxObject/cppu/source/uno/'+file+'.o')
        identity=file_identity(path,build)
        matches=[(row,m) for row in rows if pathlib.Path(row['path']) in selected for m in row['members']
                 if m['bytes']==identity['bytes'] and m['sha256']==identity['sha256']]
        if not matches or not any(symbol in m['symbols']['undefined'] for _,m in matches):
            raise ValueError('UNO编译dispatcher成员缺失或无真实静态引用: '+file)
        if symbol not in symbol_union([bridge],'strong'):
            raise ValueError('UNO真实C++ bridge静态入口缺失: '+symbol)
        cpp_rows.append({'sourceObject':identity,'staticEntry':symbol,'archive':matches[0][0]['path'],
                         'memberIndex':matches[0][1]['index']})
    icu=prefix+'icu/source/'
    embedded=require(icu+'lib/libicudata.a',False)
    stub=require(icu+'stubdata/libicudata.a')
    code=[require(icu+'lib/libicu'+name+'.a') for name in ('i18n','io','uc')]
    if symbol_union([stub],'strong')!={'_icudt78_dat'} or '_icudt78_dat' not in symbol_union(code,'undefined'):
        raise ValueError('ICU stub唯一强定义或真实代码引用无效')
    dat=build/(icu+'data/in/icudt78l.dat')
    source_dat=file_identity(dat,build)
    staged=file_identity(resources/'ICU.dat',resources)
    if (source_dat['bytes'],source_dat['sha256'])!=ICU_DATA_IDENTITY:
        raise ValueError('ICU固定官方icudt78l.dat身份不匹配')
    if not source_dat['bytes'] or (source_dat['bytes'],source_dat['sha256'])!=(staged['bytes'],staged['sha256']):
        raise ValueError('ICU官方data/in与最终staged ICU.dat不一致')
    payloads=[]
    for member in native_members(pathlib.Path(embedded['path'])):
        if '_icudt78_dat' in link_parser().macho_symbols(member['data'])['strong']:
            payload=macho_symbol_payload(member['data'],'_icudt78_dat')
            payloads.append({'bytes':len(payload),'sha256':hashlib.sha256(payload).hexdigest(),
                             'memberIndex':member['index']})
    if len(payloads)!=1 or (payloads[0]['bytes'],payloads[0]['sha256'])!=(source_dat['bytes'],source_dat['sha256']):
        raise ValueError('ICU embedded符号payload与完整外部数据不一致')
    identities=[source_dat,staged,*[entry['sourceObject'] for entry in cpp_rows]]
    return {'nss':{'libcruxPairs':len(paired),'pairs':paired,'lifecycle':sorted(lifecycle)},
            'uno':{'compiledDispatch':cpp_rows},'icu':{'bytes':source_dat['bytes'],'sha256':source_dat['sha256'],
            'source':source_dat,'staged':staged,'embeddedPayload':payloads[0]},'identityFiles':identities}


def audit_input_graph(rows, selected, public_roots=()):
    selected = {str(p) for p in selected}
    after = [row for row in rows if row['path'] in selected]
    excluded = [row for row in rows if row['path'] not in selected]
    definitions = collections.Counter(s for row in after for m in row['members'] for s in m['symbols']['strong'])
    duplicates = sorted(s for s,n in definitions.items() if n > 1)
    if duplicates:
        raise ValueError('after存在重复强定义: ' + repr(duplicates[:20]))
    before_sets = {k: symbol_union(rows,k) for k in SYMBOL_KINDS}
    after_sets = {k: symbol_union(after,k) for k in SYMBOL_KINDS}
    refs = after_sets['undefined'] | after_sets['weakUndefined'] | set(public_roots)
    lost = {}
    retained_members = member_counter(after)
    for kind in ('strong','weak','common'):
        # strong只有同名不能证明common数组的尺寸/对齐；本实现保守要求原对象仍在。
        provided = set() if kind=='common' else after_sets['strong'] | (after_sets['weak'] if kind == 'weak' else set())
        # common的尺寸/对齐未由纯parser公开，只有原对象逐字节仍保留才能证明。
        same_objects = {s for row in excluded for m in row['members']
                        if retained_members[(m['bytes'],m['sha256'])] for s in m['symbols'][kind]}
        lost[kind] = symbol_union(excluded,kind) - provided - same_objects
        downgrades = lost[kind] & (after_sets['weak'] | after_sets['common']) if kind == 'strong' else lost[kind] & after_sets['common']
        if downgrades or (lost[kind] & refs) or (kind == 'common' and lost[kind]):
            raise ValueError('排除定义丢失或降级(' + kind + '): ' + repr(sorted(downgrades | (lost[kind] & refs) | (lost[kind] if kind == 'common' else set()))[:20]))
    missing_roots = set(public_roots) - after_sets['strong']
    if missing_roots:
        raise ValueError('公开/注册根缺少真实强定义: ' + repr(sorted(missing_roots)))
    return {'before': {k:symbol_summary(v) for k,v in before_sets.items()},
            'after': {k:symbol_summary(v) for k,v in after_sets.items()},
            'lostDefinitions': {k:{**symbol_summary(v), 'symbols':sorted(v)} for k,v in lost.items()},
            'duplicateStrong': [], 'excludedConsumers': []}


def macho_symbol_payload(data, symbol):
    """按真实arm64 MH_OBJECT节和符号extent提取数据，所有偏移先验界。"""
    symbols = link_parser().macho_symbols(data)
    if symbol not in symbols['strong']:
        raise ValueError('ICU数据对象缺少强定义: ' + symbol)
    sections, symtab, cursor = [], None, 32
    ncmds, sizeofcmds = struct.unpack_from('<II', data, 16)
    for _ in range(ncmds):
        cmd,size = struct.unpack_from('<II',data,cursor)
        if cmd == 0x19:
            if size < 72:
                raise ValueError('Mach-O segment长度无效')
            nsects = struct.unpack_from('<I',data,cursor+64)[0]
            if 72 + nsects*80 != size:
                raise ValueError('Mach-O section表长度无效')
            for i in range(nsects):
                off=cursor+72+i*80
                address,length,file_offset=struct.unpack_from('<QQI',data,off+32)
                flags=struct.unpack_from('<I',data,off+64)[0]
                sections.append((address,length,file_offset,flags))
        elif cmd == 2:
            symtab=struct.unpack_from('<IIII',data,cursor+8)
        cursor += size
    if cursor != 32+sizeofcmds or symtab is None:
        raise ValueError('Mach-O数据命令无效')
    offset,count,stroff,strsize=symtab
    definitions=[]
    for i in range(count):
        index,kind,sect,desc,value=struct.unpack_from('<IBBHQ',data,offset+i*16)
        if kind & 0xe0 or (kind & 0xe) != 0xe:
            continue
        if index >= strsize or not 1 <= sect <= len(sections):
            raise ValueError('Mach-O数据符号索引越界')
        end=data.find(b'\0',stroff+index,stroff+strsize)
        if end < 0:
            raise ValueError('Mach-O数据符号名未终止')
        definitions.append((data[stroff+index:end].decode('utf-8'),sect,value))
    matches=[entry for entry in definitions if entry[0] == symbol]
    if len(matches)!=1:
        raise ValueError('ICU数据符号不是唯一实际定义')
    _,sect,value=matches[0]
    address,length,file_offset,flags=sections[sect-1]
    if flags & 0xff or not address <= value < address+length or file_offset+length > len(data):
        raise ValueError('Mach-O数据section长度或类型越界')
    end=min([v for _,s,v in definitions if s==sect and v>value]+[address+length])
    start=file_offset+value-address
    if end<=value or start+end-value>len(data):
        raise ValueError('Mach-O数据payload越界')
    return data[start:start+end-value]


def verify_aggregate(archive, expected):
    counter=collections.Counter((m['bytes'],m['sha256']) for m in native_members(archive, MAX_LINK_TOTAL))
    wanted=member_counter(expected)
    if counter != wanted:
        raise ValueError('aggregate成员多重集与selected+shim/registration不一致')
    return {'bytes':archive.stat().st_size,'sha256':sha256(archive),'members':sum(counter.values()),
            'memberMultisetSha256':hashlib.sha256(json.dumps(sorted((n,s,c) for (n,s),c in counter.items()),separators=(',',':')).encode()).hexdigest(),
            'verified':True}


class LinkAudit:
    """长原生命令前原子落盘，SIGKILL后仍能读取最后完整阶段。"""
    def __init__(self, directory):
        if directory.is_symlink() or (directory.exists() and (not directory.is_dir() or any(directory.iterdir()))):
            raise ValueError('audit-directory必须是新空普通目录')
        directory.mkdir(parents=True,exist_ok=True)
        self.directory=directory.resolve(strict=True)
        self.value={'format':'office-pdf-ios-final-link-audit-v1','phase':'starting','complete':False,
                    'inputAuditComplete':False,'aggregateAuditComplete':False,'referenceUniverseComplete':False,
                    'appleLinkVerified':False,'linkMap':None,'linkMapPlanned':False}
        self.update('starting')

    def update(self, phase, **fields):
        updated={**self.value,**fields,'phase':phase}
        raw=(json.dumps(updated,ensure_ascii=False,separators=(',',':'))+'\n').encode('utf-8')
        if len(raw)>MAX_AUDIT_BYTES:
            raise ValueError('AUDIT.json超过8MiB，拒绝截断')
        path=self.directory/'AUDIT.json'
        if path.is_symlink() or (path.exists() and not path.is_file()) or self.directory.is_symlink():
            raise ValueError('审计输出路径发生变化')
        with tempfile.NamedTemporaryFile(mode='wb',dir=self.directory,prefix='.audit-',delete=False) as stream:
            temporary=pathlib.Path(stream.name)
            try:
                stream.write(raw);stream.flush();os.fsync(stream.fileno())
            except BaseException:
                temporary.unlink(missing_ok=True)
                raise
        try:
            os.replace(temporary,path)
            self.value=updated
        finally:
            temporary.unlink(missing_ok=True)

    def capture_map(self):
        path=self.directory/'link-map.log'
        directory=self.directory.lstat()
        if not stat.S_ISDIR(directory.st_mode) or self.directory.resolve(strict=True)!=self.directory:
            raise ValueError('link-map.log父目录不是固定普通目录')
        try:
            before=path.lstat()
        except FileNotFoundError:
            return None
        def checked_identity(info):
            if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1:
                raise ValueError('link-map.log不是独立普通文件')
            if info.st_size>MAX_LINK_MAP:
                raise ValueError(f'link-map.log原文体积超限：bytes={info.st_size}，limit={MAX_LINK_MAP}')
            return (info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns,info.st_ctime_ns)
        identity=checked_identity(before)
        # 同一fd逐块摘要；NOFOLLOW/NONBLOCK避免检查与打开之间换入链接或FIFO。
        flags=os.O_RDONLY|getattr(os,'O_BINARY',0)|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_NONBLOCK',0)
        with os.fdopen(os.open(path,flags),'rb') as stream:
            if checked_identity(os.fstat(stream.fileno()))!=identity:
                raise ValueError('打开期间link-map.log身份变化')
            digest=hashlib.sha256()
            total=0
            while True:
                raw=stream.read(min(1024**2,MAX_LINK_MAP-total+1))
                if not raw:
                    break
                total+=len(raw)
                if total>MAX_LINK_MAP:
                    # 文件仍可能增长或截断；同fd的瞬时大小与已读前缀必须分开记录。
                    observed=os.fstat(stream.fileno()).st_size
                    raise ValueError(f'读取期间link-map.log原文/读取体积超限：bytes={observed}（同fd当前观测，非最终稳定大小），readBytes={total}，limit={MAX_LINK_MAP}')
                digest.update(raw)
            if checked_identity(os.fstat(stream.fileno()))!=identity or total!=before.st_size:
                raise ValueError('读取期间link-map.log身份/大小变化')
        # fd关闭后再次核对路径与父目录，不能为已被替换的路径返回旧文件摘要。
        after_directory=self.directory.lstat()
        if (checked_identity(path.lstat())!=identity or self.directory.resolve(strict=True)!=self.directory or
                not stat.S_ISDIR(after_directory.st_mode) or
                (after_directory.st_dev,after_directory.st_ino)!=(directory.st_dev,directory.st_ino)):
            raise ValueError('读取后link-map.log路径/父目录身份变化')
        return {'path':'link-map.log','bytes':total,'sha256':digest.hexdigest()}


def compact_link_rows(rows):
    """完整成员身份保留；C++符号用五类counts和规范化SHA避免无界重复展开。"""
    inputs, members = [], []
    for i,row in enumerate(rows):
        inputs.append({k:v for k,v in row.items() if k!='members'})
        for member in row['members']:
            symbols=member['symbols']
            members.append([i,member['index'],member['occurrence'],member['name'],member['bytes'],member['sha256'],
                            [len(symbols[k]) for k in SYMBOL_KINDS],
                            hashlib.sha256(json.dumps([symbols[k] for k in SYMBOL_KINDS],ensure_ascii=False,separators=(',',':')).encode()).hexdigest()])
    return {'inputs':inputs,'memberColumns':['inputIndex','index','occurrence','name','bytes','sha256',
            'symbolCounts(strong,weak,common,undefined,weakUndefined)','symbolsSha256'], 'members':members}


def unchanged_identities(entries):
    for entry in entries:
        path=pathlib.Path(entry['path'])
        if path.is_symlink() or not path.is_file() or path.stat().st_size!=entry['bytes'] or sha256(path)!=entry['sha256']:
            raise ValueError('审计期间输入身份变化: '+entry['path'])

def gnu_make():
    # Homebrew安装的是gmake；macOS系统make通常较旧，不能混用。
    for name in ('gmake', 'make'):
        path = shutil.which(name)
        if not path:
            continue
        try:
            version = run([path, '--version'])
        except (OSError, subprocess.SubprocessError):
            continue
        match = re.search(r'^GNU Make (\d+)\.(\d+)', version, re.MULTILINE)
        if match and tuple(map(int, match.groups())) >= (4, 2):
            return {'path': path, 'version': version.splitlines()[0]}
    raise ValueError('固定上游要求GNU Make >=4.2；未找到可用的gmake/make')

def collector_makefile():
    # 与上游Makefile.in一致，先选择host，避免config_host.mk展开config__lang.mk。
    # config_host的外部库参数继续引用TargetLocations宏；须等WORKDIR已载入再展开，
    # 否则官方脚本会静默在/harfbuzz等根路径查库，遗漏字体整形及文档过滤依赖。
    return ('gb_Side := host\ninclude config_host.mk\n'
            'gb_UnpackedTarball_workdir := $(WORKDIR)/UnpackedTarball\n'
            'gb_StaticLibrary_WORKDIR := $(WORKDIR)/LinkTarget/StaticLibrary\n'
            '.PHONY: office_pdf_static_inputs office_pdf_source_identity\n'
            'office_pdf_source_identity:\n\t@printf "%s" "$(SRCDIR)"\n'
            'office_pdf_static_inputs:\n\t@$(SRCDIR)/bin/lo-all-static-libs\n')

def rebuild_patched_source(source, build, make, policy):
    raw_policy = (ROOT / 'offline-policy.json').read_bytes()
    if hashlib.sha256(raw_policy).hexdigest() != policy['policySha256']:
        raise ValueError('重建前策略清单变化')
    files = json.loads(raw_policy)['files']
    # 固定LinkTarget.mk的CxxObject依赖绝对SRCDIR路径。直接进入gbuild使-W作用于
    # 实际编译依赖图；不能交给顶层递归make后假定-W会传递给子make。
    command = [make['path'], '--no-print-directory', '-f', str(source / 'Makefile.gbuild'),
               'gb_Side=host', 'BUILDDIR=' + str(build)]
    for entry in files:
        command += ['--what-if=' + str(source / entry['path'])]
    command += ['build']
    config_sha = sha256(build / 'config_host.mk')
    # 必须真实执行并成功；不接受仅修改mtime、dry-run或旧archive的身份声明。
    # stdout/stderr保留给外层CI日志，不把大型原生构建日志吞入内存。
    subprocess.check_call(command, cwd=build)
    if validate_offline_policy(source) != policy or sha256(build / 'config_host.mk') != config_sha:
        raise ValueError('重建期间源码策略或构建配置身份变化')
    return {'command': command, 'succeeded': True, 'method': 'GNU make --what-if direct gbuild',
            'configHostSha256': config_sha,
            'forcedSources': [{'path': entry['path'], 'sha256': sha256(source / entry['path'])} for entry in files]}

def validate_offline_policy(source):
    spec = importlib.util.spec_from_file_location('office_pdf_offline_policy', ROOT / 'apply_offline_policy.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    if (module.TAG, module.COMMIT) != (TAG, COMMIT):
        raise ValueError('构建器与离线策略固定身份不一致')
    return module.apply_or_verify(source, check=True)

def validate_build_compatibility(source):
    spec = importlib.util.spec_from_file_location('office_pdf_builder_compat', ROOT / 'build_compat.py')
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module.apply_or_verify(source, check=True)

def run(argv, cwd=None):
    return subprocess.check_output([str(x) for x in argv], cwd=cwd, text=True).strip()

def require_apple_tools():
    if sys.platform != 'darwin':
        raise RuntimeError('需要 macOS / Xcode；Windows只能运行源码/脚本回归')
    for tool in ('clang++', 'libtool', 'lipo', 'vtool', 'nm'):
        run(['xcrun', '--find', tool])
    run(['xcodebuild', '-version'])

def sha256(path):
    digest = hashlib.sha256()
    with path.open('rb') as stream:
        while True:
            chunk = stream.read(1024 * 1024)
            if not chunk:
                break
            digest.update(chunk)
    return digest.hexdigest()

def inventory(root):
    root = pathlib.Path(root)
    result = []
    for path in sorted(root.rglob('*')):
        if path.is_symlink():
            raise ValueError('resource symlink refused: ' + str(path))
        if path.is_file():
            result.append({'path': path.relative_to(root).as_posix(), 'bytes': path.stat().st_size,
                           'sha256': sha256(path)})
        elif not path.is_dir():
            raise ValueError('non-regular resource: ' + str(path))
    if not result:
        raise ValueError('resources empty')
    return result

def validate_resource_layout(root):
    for name in ('program', 'share'):
        if not (root / name).is_dir():
            raise ValueError('expected iOS resource directory: ' + name)
    for name in ('rc', 'fundamentalrc', 'ICU.dat'):
        if not (root / name).is_file() or (root / name).stat().st_size == 0:
            raise ValueError('expected iOS bootstrap resource: ' + name)

def registration_inputs(build):
    paths = [build / 'workdir/CustomTarget/ios/native-code.h']
    paths += [build / 'config_host' / name for name in
              ('config_crypto.h', 'config_features.h', 'config_fuzzers.h', 'config_gpgme.h', 'config_locales.h')]
    for path in paths:
        if path.is_symlink() or not path.resolve().is_relative_to(build) or not path.is_file() or path.stat().st_size == 0:
            raise ValueError('missing/unsafe generated iOS registration input: ' + str(path))
    header = paths[0].read_text(encoding='utf-8')
    for symbol in ('lo_get_factory_map', 'lo_get_constructor_map'):
        if symbol not in header:
            raise ValueError('generated iOS registration header lacks ' + symbol)
    return [{'path': path.relative_to(build).as_posix(), 'bytes': path.stat().st_size, 'sha256': sha256(path)} for path in paths]

def validate_registration_symbols(symbols):
    for name in ('lo_get_factory_map', 'lo_get_constructor_map'):
        if '_' + name not in symbols.splitlines():
            raise ValueError('registration object lacks unmangled C symbol: ' + name)

def link_inputs(text, build):
    result = []
    for item in shlex.split(text):
        path = pathlib.Path(item)
        if not path.is_absolute():
            path = build / path
        if '*' in str(path) or '?' in str(path) or path.suffix not in ('.a', '.o'):
            raise ValueError('unexpanded/malformed native input: ' + item)
        path = path.resolve()
        if not path.is_relative_to(build) or not path.is_file():
            raise ValueError('native input outside build: ' + item)
        if path not in result:
            result.append(path)
    if not result:
        raise ValueError('empty LibreOffice static inputs')
    return result

def ios_link_inputs(text, build):
    # 固定LO 26.2.6.3的lo-all-static-libs全集继续保留；这里只补官方
    # RepositoryExternal.mk及NSS3.128 freebl/Makefile中已确认的漏项。
    # 不扫全树、不选内部替代archive；缺失/逃逸沿用同一失败门禁。
    build = build.resolve(strict=True)
    inputs = link_inputs(text, build)
    unpacked = build / 'workdir/UnpackedTarball'
    configured = ('harfbuzz/builddir/src/libharfbuzz.a',)
    expected = link_inputs(shlex.join(str(unpacked / name) for name in configured), build)
    if any(path not in inputs for path in expected):
        raise ValueError('官方静态收集器遗漏配置依赖；须检查gbuild路径展开')
    # m4内部模式的EBOOK_LIBS/FREEHAND_LIBS为空；RepositoryExternal直接加这两库，
    # 不能误要求它们必须已在lo-all-static-libs基于环境变量的输出中。
    supplemental = ['libebook/src/lib/.libs/libe-book-0.1.a',
                    'libfreehand/src/lib/.libs/libfreehand-0.1.a',
                    'libetonyek/src/lib/.libs/libetonyek-0.1.a',
                    'libpagemaker/src/lib/.libs/libpagemaker-0.0.a',
                    'libstaroffice/src/lib/.libs/libstaroffice-0.0.a',
                    'libqxp/src/lib/.libs/libqxp-0.0.a',
                    'libzmf/src/lib/.libs/libzmf-0.0.a',
                    'libxslt/libexslt/.libs/libexslt.a']
    supplemental += ['nss/nss/lib/freebl/out/Darwin_SINGLE_SHLIB/aarch64-gcm-slothy/gcm-' + bits + '-' + direction + '.o'
                     for bits in ('128', '192', '256') for direction in ('enc', 'dec')]
    for path in link_inputs(shlex.join(str(unpacked / name) for name in supplemental), build):
        if path not in inputs:
            inputs.append(path)
    return inputs

def build_kernel(args):
    # CI可先创建空目录；无显式目录的直接调用也在临时工作目录外保留失败证据。
    directory=getattr(args,'audit_directory',None) or args.output.with_name(args.output.name+'.audit')
    audit_path=directory.resolve()
    output=args.output.resolve()
    roots=[getattr(args,name).resolve() for name in ('source','build','resources')]
    if audit_path==output or audit_path.is_relative_to(output) or output.is_relative_to(audit_path) or any(
            audit_path==root or audit_path.is_relative_to(root) or root.is_relative_to(audit_path) for root in roots):
        raise ValueError('audit-directory不得与输入树或候选输出重叠')
    audit=LinkAudit(directory)
    try:
        return _build_kernel(args,audit)
    except BaseException as error:
        # SIGKILL不执行这里；各长步骤前的原子阶段文件才是最低持久化保证。
        failed_phase=audit.value['phase']
        linkmap,map_failure=None,None
        try:
            linkmap=audit.capture_map()
        except (ValueError,OSError) as map_error:
            map_failure={'type':type(map_error).__name__,'message':str(map_error)[:4000]}
        try:
            audit.update('failed',complete=False,appleLinkVerified=False,
                         failure={'phase':failed_phase,'type':type(error).__name__,'message':str(error)[:4000]},
                         linkMap=linkmap,mapCaptureFailure=map_failure)
        except BaseException as export_error:
            try:
                print(json.dumps({'auditExportFailure':{'type':type(export_error).__name__,'message':str(export_error)[:4000]},
                                  'originalBuildFailure':{'type':type(error).__name__,'message':str(error)[:4000]}},ensure_ascii=False),file=sys.stderr)
            except BaseException:
                # 最后诊断管道也可能失败；仍由外层bare raise保留原native异常对象。
                pass
        raise


def _build_kernel(args,audit):
    require_apple_tools()
    source = args.source.resolve(strict=True)
    build = args.build.resolve(strict=True)
    resources = args.resources.resolve(strict=True)
    if args.output.exists():
        raise ValueError('output already exists; choose a new output directory')
    if run(['git', 'describe', '--tags', '--exact-match', 'HEAD'], source) != TAG:
        raise ValueError('source tag mismatch')
    commit = run(['git', 'rev-parse', 'HEAD'], source)
    if commit != COMMIT:
        raise ValueError('source commit does not match official pinned tag')
    policy = validate_offline_policy(source)
    compatibility = validate_build_compatibility(source)
    acceptance_only = getattr(args, 'acceptance_only', False)
    config = (build / 'config_host.mk').read_text()
    if 'iOS' not in config or 'arm64' not in config:
        raise ValueError('not a configured arm64 iOS LibreOffice build')
    make = gnu_make()
    validate_resource_layout(resources)
    kernel_sources=[file_identity(ROOT/relative,ROOT) for relative in
                    ('src/OfficePdfKernel.mm','src/OfficePdfRegistration.cxx','include/OfficePdfKernel.h',
                     'include/module.modulemap','ci/inspect_link.py')]
    audit.update('validated',sourceTag=TAG,sourceCommit=commit,offlinePolicy=policy,buildCompatibility=compatibility,
                 configHost=file_identity(build/'config_host.mk',build),kernelSourceFiles=kernel_sources)
    # 配置驱动官方全集，加固定版本审计补集；保留.a及NSS单独.o。
    with tempfile.TemporaryDirectory(prefix='office-pdf-ios-') as temporary:
        work = pathlib.Path(temporary)
        makefile = work / 'collect.mk'
        makefile.write_text(collector_makefile(), encoding='utf-8', newline='\n')
        actual_source = run([make['path'], '--no-print-directory', '-s', '-f', makefile, 'office_pdf_source_identity'], build)
        if pathlib.Path(actual_source).resolve() != source:
            raise ValueError('configured build source does not match pinned source')
        audit.update('rebuild')
        rebuilt = rebuild_patched_source(source, build, make, policy)
        if validate_build_compatibility(source) != compatibility:
            raise ValueError('重建期间构建兼容身份变化')
        actual_source = run([make['path'], '--no-print-directory', '-s', '-f', makefile, 'office_pdf_source_identity'], build)
        if pathlib.Path(actual_source).resolve() != source:
            raise ValueError('rebuilt source identity changed')
        profile=validate_link_profile(source,build)
        collector=work/'collector.txt'
        with collector.open('wb') as stream:
            subprocess.run([make['path'],'--no-print-directory','-s','-f',str(makefile),'office_pdf_static_inputs'],
                           cwd=build,stdout=stream,check=True)
        if collector.stat().st_size>1024**2:
            raise ValueError('原始collector输出超过1MiB')
        collector_text=collector.read_bytes().decode('utf-8')
        raw_inputs=link_inputs(collector_text,build)
        inputs = ios_link_inputs(collector_text, build)
        registrations = registration_inputs(build)
        resource_files = inventory(resources)
        audit.update('compile-shim',upstreamRebuild=rebuilt,profile=profile,
                     collector={'text':collector_text,'bytes':collector.stat().st_size,'sha256':sha256(collector),
                                'rawInputs':[str(p.relative_to(build)) for p in raw_inputs],
                                'supplementalInputs':[str(p.relative_to(build)) for p in inputs if p not in raw_inputs]},
                     nativeRegistration=registrations)
        for path in inputs:
            if run(['xcrun', 'lipo', '-archs', path]).split() != ['arm64']:
                raise ValueError('input is not exclusively arm64: ' + str(path))
        sdk = run(['xcrun', '--sdk', 'iphoneos', '--show-sdk-path'])
        obj = work / 'OfficePdfKernel.o'
        run(['xcrun', '--sdk', 'iphoneos', 'clang++', '-std=c++17', '-fobjc-arc', '-DIOS',
             '-DOFFICE_PDF_ACCEPTANCE_ONLY=' + ('1' if acceptance_only else '0'),
             '-DOFFICE_PDF_POLICY_SHA256="' + policy['policySha256'] + '"',
             '-target', 'arm64-apple-ios' + MIN_IOS, '-isysroot', sdk, '-I', source / 'include',
             '-I', ROOT / 'include', '-c', ROOT / 'src/OfficePdfKernel.mm', '-o', obj])
        registration_obj = work / 'OfficePdfRegistration.o'
        audit.update('compile-registration')
        run(['xcrun', '--sdk', 'iphoneos', 'clang++', '-std=c++17', '-DIOS', '-DDISABLE_DYNLOADING',
             '-target', 'arm64-apple-ios' + MIN_IOS, '-isysroot', sdk,
             '-I', build / 'config_host', '-I', build / 'include', '-I', source / 'include',
             '-I', build / 'workdir/CustomTarget/ios', '-c', ROOT / 'src/OfficePdfRegistration.cxx', '-o', registration_obj])
        # Apple nm只列定义的外部符号；C++改名或遗漏注册表必须在归档前失败。
        validate_registration_symbols(run(['xcrun', 'nm', '-gUj', registration_obj]))
        audit.update('scan-inputs')
        rows=scan_link_inputs([*inputs,obj,registration_obj],build)
        audit.update('normalize',referenceUniverseComplete=True,**compact_link_rows(rows))
        inputs,rules=normalize_ios_link_inputs(inputs,build,rows)
        all_selected=[*inputs,obj,registration_obj]
        # 公开C ABI和真实注册根都进入引用根，不能以“没有静态consumer”为由删除。
        public_roots=['_OfficePdfKernelProbeJSON','_OfficePdfKernelConvertJSON',
                      '_OfficePdfKernelAcceptanceConvertJSON','_OfficePdfKernelFreeString',
                      '_lo_get_factory_map','_lo_get_constructor_map']
        symbols=audit_input_graph(rows,all_selected,public_roots)
        contracts=validate_ios_families(rows,all_selected,build,resources)
        selected_rows=[row for row in rows if pathlib.Path(row['path']) in all_selected]
        identities=[{k:row[k] for k in ('path','bytes','sha256')} for row in rows]
        identities+=profile['files']+contracts['identityFiles']+kernel_sources
        identities+=[file_identity(build/entry['path'],build) for entry in registrations]
        unchanged_identities(identities)
        audit.update('aggregate',rules=rules,selectedInputIndices=[i for i,row in enumerate(rows) if pathlib.Path(row['path']) in all_selected],
                     symbols=symbols,contracts=contracts,publicRoots=public_roots,inputAuditComplete=True)
        archive = work / 'OfficePdfKernel'
        run(['xcrun', 'libtool', '-static', '-o', archive, obj, registration_obj, *inputs])
        aggregate=verify_aggregate(archive,selected_rows)
        unchanged_identities(identities)
        audit.update('aggregate-verified',aggregate=aggregate,aggregateAuditComplete=True)
        # 链接真实可执行探针，防止仅生成archive却有未满足的LO/C++/系统依赖。
        probe = work / 'probe.mm'
        probe.write_text('#include "OfficePdfKernel.h"\nint main(){auto p=OfficePdfKernelProbeJSON(0);OfficePdfKernelFreeString(p);return 0;}\n')
        executable = work / 'probe'
        # NSS Darwin默认使用系统SQLite；必须链接目标iPhoneOS SDK的sqlite3，
        # 不能凭主机检测结果查找一个不存在的libsqlite3.a或省略真实未定义符号。
        system_libraries = ('z', 'iconv', 'xml2', 'c++', 'sqlite3')
        framework_flags = []
        for name in ('Foundation', 'UIKit', 'CoreGraphics', 'CoreText', 'CoreFoundation',
                     'QuartzCore', 'Security', 'CFNetwork', 'SystemConfiguration', 'MobileCoreServices',
                     'ImageIO', 'Accelerate'):
            framework_flags += ['-framework', name]
        command=['xcrun', '--sdk', 'iphoneos', 'clang++', '-std=c++17', '-target', 'arm64-apple-ios' + MIN_IOS,
             '-isysroot', sdk, '-I', ROOT / 'include', probe, '-Wl,-force_load,' + str(archive),
             '-Wl,-map,'+str(audit.directory/'link-map.log'),
             *['-l' + name for name in system_libraries], *framework_flags, '-o', executable]
        audit.update('link',linkCommand=[str(p) for p in command],linkMapPlanned=True,
                     systemLibraries=list(system_libraries),frameworkFlags=framework_flags)
        run(command)
        platform = run(['xcrun', 'vtool', '-show-build', executable])
        if 'platform IOS' not in platform:
            raise ValueError('linked probe is not an iOS device executable')
        linkmap=audit.capture_map()
        if linkmap is None or not linkmap['bytes']:
            raise ValueError('真实链接未留下非空link-map.log')
        unchanged_identities(identities)
        if validate_offline_policy(source)!=policy or validate_build_compatibility(source)!=compatibility or inventory(resources)!=resource_files:
            raise ValueError('最终链接期间源策略/兼容或资源身份变化')
        audit.update('package',linkMap=linkmap,platform=platform,inputsUnchanged=True)
        args.output.mkdir(parents=True)
        framework = args.output / 'OfficePdfKernel.framework'
        (framework / 'Headers').mkdir(parents=True)
        (framework / 'Modules').mkdir()
        shutil.copy2(archive, framework / 'OfficePdfKernel')
        shutil.copy2(ROOT / 'include/OfficePdfKernel.h', framework / 'Headers')
        shutil.copy2(ROOT / 'include/module.modulemap', framework / 'Modules')
        import plistlib
        (framework / 'Info.plist').write_bytes(plistlib.dumps({'CFBundleIdentifier': 'com.lizhao.office-pdf.kernel',
            'CFBundleName': 'OfficePdfKernel', 'CFBundleExecutable': 'OfficePdfKernel', 'CFBundlePackageType': 'FMWK',
            'CFBundleVersion': '1', 'CFBundleShortVersionString': '1.0', 'MinimumOSVersion': MIN_IOS}))
        shutil.copytree(resources, args.output / 'OfficePdfKernelResources.bundle')
        (args.output / 'OfficePdfKernelResources.bundle/OfficePdfKernelManifest.json').write_text(
            json.dumps({'sourceTag': TAG, 'sourceCommit': commit, 'offlinePolicy': policy,
                        'buildCompatibility': compatibility, 'resources': resource_files}, indent=2) + '\n', encoding='utf-8')
        (args.output / 'AppRootResources').mkdir()
        shutil.copy2(resources / 'ICU.dat', args.output / 'AppRootResources/ICU.dat')
        final_data=[file_identity(args.output/name,args.output) for name in
                    ('OfficePdfKernelResources.bundle/ICU.dat','AppRootResources/ICU.dat')]
        if any((entry['bytes'],entry['sha256'])!=(contracts['icu']['bytes'],contracts['icu']['sha256']) for entry in final_data):
            raise ValueError('ICU最终bundle/AppRootResources数据链不一致')
        shutil.copy2(executable, args.output / 'link-probe')
        xcode=run(['xcodebuild','-version'])
        unchanged_identities(identities)
        if audit.capture_map()!=linkmap:
            raise ValueError('打包期间link-map.log身份变化')
        audit.update('complete',complete=True,appleLinkVerified=True,finalICUResources=final_data,linkMap=linkmap)
        shutil.copy2(audit.directory/'AUDIT.json',args.output/'AUDIT.json')
        shutil.copy2(audit.directory/'link-map.log',args.output/'link-map.log')
        copied_map=args.output/'link-map.log'
        if copied_map.stat().st_size!=linkmap['bytes'] or sha256(copied_map)!=linkmap['sha256']:
            raise ValueError('候选link-map.log复制身份不一致')
        manifest = {'sourceTag': TAG, 'sourceCommit': commit, 'architecture': 'arm64', 'platform': 'iOS',
            'minimumIOS': MIN_IOS, 'offlinePolicy': policy, 'buildCompatibility': compatibility, 'acceptanceOnly': acceptance_only,
            'systemLibraries': list(system_libraries),
            'gnuMake': make, 'upstreamRebuild': rebuilt,
            'shimSourceSha256': sha256(ROOT / 'src/OfficePdfKernel.mm'),
            'registrationSourceSha256': sha256(ROOT / 'src/OfficePdfRegistration.cxx'),
            'nativeRegistration': registrations,
            'appleLinkVerified': True, 'deviceRuntimeVerified': False, 'strictOffline': False, 'available': False,
            'reason': 'IOS_OFFLINE_POLICY_UNQUALIFIED', 'resources': resource_files,
            'inputs': [{'path': str(p.relative_to(build)), 'bytes': p.stat().st_size,
                        'sha256': sha256(p)} for p in inputs],
            'finalLinkAudit':{'path':'AUDIT.json','sha256':sha256(args.output/'AUDIT.json'),'linkMap':audit.value['linkMap']},
            'artifacts': inventory(args.output), 'xcode': xcode}
        (args.output / 'BUILD.json').write_text(json.dumps(manifest, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')

def main():
    parser = argparse.ArgumentParser(description=__doc__)
    for flag in ('source', 'build', 'resources', 'output'):
        parser.add_argument('--' + flag, type=pathlib.Path, required=True)
    parser.add_argument('--acceptance-only', action='store_true',
                        help='仅启用独立原生验收C ABI；不解除生产入口门禁，不供业务基座使用')
    parser.add_argument('--audit-directory',type=pathlib.Path,
                        help='新空普通目录；长原生命令前原子保留AUDIT.json与真实link-map.log')
    args = parser.parse_args()
    try:
        build_kernel(args)
    except (ValueError, OSError, RuntimeError, subprocess.CalledProcessError) as error:
        parser.exit(1, '构建失败（未证明iOS可用）: ' + str(error) + '\n')

if __name__ == '__main__':
    main()

"""只传输成功 make 边界的公开构建树；缓存不承担资格或发布证明。"""
import hashlib
import decimal
import json
import os
import pathlib
import posixpath
import re
import shutil
import tarfile
import time

ROOTS = ('libreoffice-source', 'libreoffice-build')
PHASES = ('tools', 'vcl', 'sd', 'sw', 'final')
TARGETS = ('cross-toolset', 'vcl.allbuild', 'sd.allbuild', 'sw.allbuild', 'build')
MAX_CACHE_BYTES = 4 * 1024**3
CACHE_OVERHEAD_BYTES = 64 * 1024**2
MAX_EXPANDED_BYTES = 40 * 1024**3
MAX_MEMBERS = 500000
FORMAT = 'office-pdf-ios-checkpoint-v1'


def check_deadline(deadline):
    if deadline is not None and time.monotonic() >= deadline:
        raise RuntimeError('检查点达到本阶段内部时限')


def mtime_ns(item):
    try:
        value = decimal.Decimal(item.pax_headers.get('mtime', str(item.mtime))) * 1000000000
        if not value.is_finite() or value != value.to_integral_value() or abs(value) > 2**63-1:
            raise ValueError('归档 mtime 超限或不足纳秒精度')
        return int(value)
    except decimal.InvalidOperation as error:
        raise ValueError('归档 mtime 无效') from error


def predecessor(phase):
    if phase not in PHASES:
        raise ValueError('未知构建阶段')
    index = PHASES.index(phase)
    return PHASES[index-1] if index else None


def target(phase):
    predecessor(phase)
    return TARGETS[PHASES.index(phase)]


def sha256(path):
    value = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024*1024), b''):
            value.update(chunk)
    return value.hexdigest()


def cache_key(identity, phase):
    predecessor(phase)
    digest = hashlib.sha256(json.dumps(identity, sort_keys=True, separators=(',', ':')).encode()).hexdigest()
    return FORMAT + '-' + digest + '-' + phase


def clean_name(name, roots=ROOTS):
    if not isinstance(name, str) or not name or '\\' in name or ':' in name or '\x00' in name:
        raise ValueError('归档路径无效')
    path = pathlib.PurePosixPath(name)
    if path.is_absolute() or any(p in ('', '.', '..') for p in name.split('/')) or path.parts[0] not in roots:
        raise ValueError('归档路径逃逸')
    return path


def link_destination(name, link, work, roots=ROOTS):
    if not link or '\\' in link or '\x00' in link or ':' in link:
        raise ValueError('归档链接无效')
    if link.startswith('/'):
        prefix = work.as_posix().rstrip('/') + '/'
        if not link.startswith(prefix):
            raise ValueError('绝对链接逃逸')
        value = link[len(prefix):]
    else:
        value = posixpath.join(posixpath.dirname(name), link)
    value = posixpath.normpath(value)
    clean_name(value, roots)
    return value


def audit(payload, work, deadline=None, roots=ROOTS):
    """先完整审计，再由调用者解包；不调用 extract/extractall。"""
    members = {}
    aliases = set()
    expanded = 0
    with tarfile.open(payload, 'r:gz') as archive:
        for item in archive:
            check_deadline(deadline)
            clean_name(item.name, roots)
            alias = item.name.casefold()
            if alias in aliases or len(members) >= MAX_MEMBERS:
                raise ValueError('归档重复路径或条目超限')
            aliases.add(alias)
            if not (item.isdir() or item.isfile() or item.issym()):
                raise ValueError('拒绝硬链接、特殊文件或未知 tar 类型')
            if item.mode & ~0o777 or item.size < 0:
                raise ValueError('归档权限或长度无效')
            mtime_ns(item)
            if item.isfile():
                expanded += item.size
                if expanded > MAX_EXPANDED_BYTES:
                    raise ValueError('归档展开体积超限')
            members[item.name] = item
    # 任何文件或链接都不能成为其他归档项的写入祖先。
    for name, item in members.items():
        for parent in pathlib.PurePosixPath(name).parents:
            ancestor = members.get(parent.as_posix())
            if ancestor and not ancestor.isdir():
                raise ValueError('归档非目录祖先')
        if item.issym():
            current = link_destination(name, item.linkname, work, roots)
            visited = {name}
            for _ in range(100):
                parts = pathlib.PurePosixPath(current).parts
                replacement = None
                for index in range(1, len(parts)+1):
                    part = '/'.join(parts[:index])
                    entry = members.get(part)
                    if entry and entry.issym():
                        if part in visited:
                            raise ValueError('归档链接环')
                        visited.add(part)
                        replacement = posixpath.normpath(posixpath.join(
                            link_destination(part, entry.linkname, work, roots), *parts[index:]))
                        clean_name(replacement, roots)
                        break
                if replacement is None:
                    break
                current = replacement
            else:
                raise ValueError('归档链接链超限')
    if any(name not in members or not members[name].isdir() for name in roots):
        raise ValueError('归档缺少精确允许根')
    return members, expanded


def config_identity(work):
    root = work / ROOTS[1]
    return {p.relative_to(root).as_posix(): sha256(p) for p in sorted(root.glob('config*.mk')) if p.is_file() and not p.is_symlink()}


def save(work, output, identity, phase, deadline=None):
    predecessor(phase)
    if phase == 'final':
        raise ValueError('final 不保存续编检查点')
    return _save(work, output, identity, phase, deadline, ROOTS, 'build')


def save_candidate(candidate, output, identity, deadline=None):
    if candidate.name != 'candidate' or candidate.is_symlink() or not candidate.is_dir():
        raise ValueError('最终候选目录无效')
    if not any(candidate.iterdir()):
        raise ValueError('最终候选为空')
    return _save(candidate.parent, output, identity, 'final', deadline, ('candidate',), 'candidate')


def _save(work, output, identity, phase, deadline, roots, kind):
    if output.exists() or output.is_symlink():
        raise ValueError('拒绝覆盖检查点目录')
    started = time.monotonic()
    work = work.resolve(strict=True)
    output.mkdir()
    payload = output / 'payload.tar.gz'
    with tarfile.open(payload, 'w:gz', format=tarfile.PAX_FORMAT, compresslevel=6) as archive:
        for name in roots:
            root = work / name
            if not root.is_dir() or root.is_symlink():
                raise ValueError('检查点构建根无效')
            for path in (root, *sorted(root.rglob('*'))):
                check_deadline(deadline)
                relative = path.relative_to(work).as_posix()
                clean_name(relative, roots)
                archive.inodes.clear()  # 硬链接按独立文件保真，恢复不接受 tar 硬链接。
                item = archive.gettarinfo(str(path), relative)
                # PAX 标准 mtime 保留原始纳秒，避免跨 job 浮点舍入破坏 make 的增量关系。
                original_ns = path.lstat().st_mtime_ns
                seconds, nanos = divmod(abs(original_ns), 1000000000)
                item.pax_headers['mtime'] = ('-' if original_ns < 0 else '') + str(seconds) + '.' + f'{nanos:09d}'
                item.uid = item.gid = 0
                item.uname = item.gname = ''
                if item.isfile():
                    with path.open('rb') as stream:
                        archive.addfile(item, stream)
                else:
                    archive.addfile(item)
                if payload.stat().st_size + CACHE_OVERHEAD_BYTES > MAX_CACHE_BYTES:
                    raise ValueError('检查点超出 4GiB 免费传输预算')
    members, expanded = audit(payload, work, deadline, roots)
    manifest = {'format': FORMAT, 'kind': kind, 'archiveRoots': list(roots), 'identity': identity, 'phase': phase, 'target': target(phase),
                'payloadSha256': sha256(payload), 'payloadBytes': payload.stat().st_size,
                'expandedBytes': expanded, 'members': len(members), 'config': config_identity(work) if kind == 'build' else {}}
    manifest_path = output / 'manifest.json'
    manifest_path.write_text(json.dumps(manifest, ensure_ascii=False, sort_keys=True, indent=2)+'\n', encoding='utf-8')
    total = payload.stat().st_size + manifest_path.stat().st_size + CACHE_OVERHEAD_BYTES
    if total > MAX_CACHE_BYTES:
        raise ValueError('检查点及开销超出 4GiB 免费传输预算')
    check_deadline(deadline)
    return {**manifest, 'cacheKey': cache_key(identity, phase), 'manifestSha256': sha256(manifest_path),
            'accountedCacheBytes': total, 'seconds': time.monotonic()-started}


def restore(work, directory, identity, phase, expected_payload, expected_manifest, deadline=None):
    previous = predecessor(phase)
    if previous is None:
        raise ValueError('初始阶段禁止恢复检查点')
    started = time.monotonic()
    payload = directory / 'payload.tar.gz'
    manifest_path = directory / 'manifest.json'
    if directory.is_symlink() or not directory.is_dir() or {p.name for p in directory.iterdir()} != {'payload.tar.gz', 'manifest.json'}:
        raise ValueError('缓存缺失或结构无效')
    for path in (payload, manifest_path):
        if path.is_symlink() or not path.is_file():
            raise ValueError('检查点文件无效')
    if payload.stat().st_size + manifest_path.stat().st_size + CACHE_OVERHEAD_BYTES > MAX_CACHE_BYTES or manifest_path.stat().st_size > 65536:
        raise ValueError('检查点体积超限')
    if not re.fullmatch('[a-f0-9]{64}', expected_payload) or not re.fullmatch('[a-f0-9]{64}', expected_manifest):
        raise ValueError('缺少前 job 受信 SHA')
    if sha256(payload) != expected_payload or sha256(manifest_path) != expected_manifest:
        raise ValueError('检查点 SHA 不符')
    manifest = json.loads(manifest_path.read_text(encoding='utf-8'))
    if not isinstance(manifest, dict) or manifest.get('format') != FORMAT or manifest.get('kind') != 'build' or manifest.get('archiveRoots') != list(ROOTS) or manifest.get('identity') != identity or manifest.get('phase') != previous or manifest.get('target') != target(previous):
        raise ValueError('检查点身份或阶段顺序不符')
    work = work.resolve(strict=True)
    for name in ROOTS:
        if (work / name).exists() or (work / name).is_symlink():
            raise ValueError('拒绝覆盖恢复根')
    members, expanded = audit(payload, work, deadline)
    if manifest.get('payloadSha256') != expected_payload or manifest.get('payloadBytes') != payload.stat().st_size or manifest.get('expandedBytes') != expanded or manifest.get('members') != len(members):
        raise ValueError('检查点清单与归档不符')
    if shutil.disk_usage(work).free < expanded + 1024**3:
        raise ValueError('恢复磁盘不足，禁止清理其他文件')
    # 审计完成后占有两个新根，再写普通文件。仅最后创建 symlink。
    for name in ROOTS:
        (work/name).mkdir()
    with tarfile.open(payload, 'r:gz') as archive:
        for item in members.values():
            check_deadline(deadline)
            path = work / item.name
            path.parent.mkdir(parents=True, exist_ok=True)
            if item.isdir():
                path.mkdir(exist_ok=True)
            elif item.isfile():
                with archive.extractfile(item) as source, path.open('xb') as destination:
                    shutil.copyfileobj(source, destination, 1024*1024)
                path.chmod(item.mode)
                os.utime(path, ns=(mtime_ns(item), mtime_ns(item)))
        for item in members.values():
            if item.issym():
                path = work / item.name
                path.symlink_to(item.linkname)
                if os.utime in os.supports_follow_symlinks:
                    os.utime(path, ns=(mtime_ns(item), mtime_ns(item)), follow_symlinks=False)
        for item in sorted(members.values(), key=lambda p: p.name.count('/'), reverse=True):
            if item.isdir():
                path = work / item.name
                path.chmod(item.mode)
                os.utime(path, ns=(mtime_ns(item), mtime_ns(item)))
    if config_identity(work) != manifest.get('config'):
        raise ValueError('恢复配置 SHA 不符')
    check_deadline(deadline)
    return {'restored': True, 'phase': previous, 'expandedBytes': expanded,
            'members': len(members), 'seconds': time.monotonic()-started}

