def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=True).encode()


def digest(data):
    return hashlib.sha256(data).hexdigest()


def unique_json(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError('拒绝重复JSON字段：' + key)
        result[key] = value
    return result


def read_json(path):
    if path.is_symlink() or path.stat().st_size > MAX_FILE:
        raise ValueError('JSON文件路径或体积无效')
    return json.loads(path.read_text(encoding='utf-8'), object_pairs_hook=unique_json)


def clean_make_environment(env):
    result = env.copy()
    for key in ('MAKEFILES', 'MAKEFLAGS', 'GNUMAKEFLAGS', 'MFLAGS'):
        if result.get(key):
            raise ValueError('拒绝GNUmake环境注入：' + key)
        result.pop(key, None)
    return result


def file_sha(path):
    result = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024**2), b''):
            result.update(chunk)
    return result.hexdigest()


def validate_receipt(value):
    if not isinstance(value, dict) or set(value) != {'format', 'checkpoint', 'sourceFiles'} or value['format'] != 'office-pdf-ios-inspect-receipt-v1':
        raise ValueError('诊断回执结构无效')
    if digest(canonical(value['checkpoint'])) != CHECKPOINT_SHA or digest(canonical(value['sourceFiles'])) != SOURCES_SHA:
        raise ValueError('第七轮回执/原30项源码身份被改变')
    return value['checkpoint']


def validate_host(original, current):
    allowed = {'GITHUB_RUN_ID', 'GITHUB_RUN_ATTEMPT', 'GITHUB_SHA', 'kernelManifestSha256'}
    if {k: v for k, v in original.items() if k not in allowed} != {k: v for k, v in current.items() if k not in allowed}:
        raise ValueError('真实主机、路径、工具链、包清单或驱动身份与第七轮不符')


class Evidence:
    def __init__(self, directory):
        self.directory = directory
        self.deadline = time.monotonic() + 25 * 60
        self.index = 0

    def check(self):
        if time.monotonic() >= self.deadline:
            raise RuntimeError('只读诊断达到25分钟内部时限')
        sizes = [p.stat().st_size for p in self.directory.iterdir() if p.is_file()]
        if any(n > MAX_FILE for n in sizes) or sum(sizes) > MAX_OUTPUT - 8192:
            raise ValueError('证据体积超限；未截断证据')

    def write(self, name, data):
        self.check()
        if len(data) > MAX_FILE or sum(p.stat().st_size for p in self.directory.iterdir() if p.is_file()) + len(data) > MAX_OUTPUT - 8192:
            raise ValueError('证据体积超限；拒绝写入，未静默截断')
        with (self.directory / name).open('xb') as stream:
            stream.write(data)

    def json(self, name, value):
        self.write(name, json.dumps(value, ensure_ascii=False, separators=(',', ':')).encode('utf-8') + b'\n')

    def command(self, argv, cwd=None, env=None):
        self.check()
        self.index += 1
        label = f'{self.index:02d}'
        self.json(label + '-command.json', {'argv': list(map(str, argv)), 'cwd': str(cwd) if cwd else None})
        path = self.directory / (label + '-output.log')
        print('只读诊断命令 ' + label, flush=True)
        with path.open('xb') as log, selectors.DefaultSelector() as selector:
            process = subprocess.Popen(list(map(str, argv)), cwd=cwd, env=env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, start_new_session=True)
            selector.register(process.stdout, selectors.EVENT_READ)
            captured = 0
            previous = sum(p.stat().st_size for p in self.directory.iterdir() if p.is_file())
            try:
                while selector.get_map():
                    self.check()
                    for key, _ in selector.select(timeout=0.1):
                        chunk = os.read(key.fileobj.fileno(), 65536)
                        if not chunk:
                            selector.unregister(key.fileobj)
                            continue
                        captured += len(chunk)
                        if captured > MAX_FILE or previous + captured > MAX_OUTPUT - 8192:
                            raise ValueError('命令输出超限，已停止；日志不完整且诊断失败')
                        log.write(chunk)
                        log.flush()
                process.wait(timeout=max(0.1, self.deadline - time.monotonic()))
                self.check()
                if process.returncode:
                    raise RuntimeError('诊断命令失败：' + label)
            finally:
                try:
                    os.killpg(process.pid, signal.SIGKILL)
                except ProcessLookupError:
                    pass
                process.wait()
                process.stdout.close()
        return path.read_text(encoding='utf-8')


def finish_success(evidence):
    """所有证据完成后才写终结回执；最终预算检查失败时撤回成功回执。"""
    evidence.check()
    index = []
    for path in sorted(evidence.directory.iterdir()):
        if path.is_symlink() or not path.is_file() or path.name == 'RESULT.json':
            raise ValueError('证据索引发现非普通文件或已有终结回执')
        index.append({'path': path.name, 'bytes': path.stat().st_size, 'sha256': file_sha(path)})
    result_path = evidence.directory/'RESULT.json'
    try:
        evidence.json('RESULT.json', {'inspectionComplete': True, 'inspectionOnly': True, 'candidateBuilt': False,
            'appleLinkVerified': False, 'deviceRuntimeVerified': False, 'referenceUniverseComplete': False,
            'cacheSaved': False, 'evidence': index})
        evidence.check()
    except BaseException:
        if result_path.is_file():
            result_path.unlink()
        raise


def archive_members(data, max_bytes=MAX_ARCHIVE, max_members=MAX_MEMBERS):
    """解析普通 BSD/GNU ar；原始字节切片，不解包、不合并同名成员。"""
    if len(data) > max_bytes or not data.startswith(b'!<arch>\n'):
        raise ValueError('archive体积或格式无效（不支持thin archive）')
    cursor, ordinal, names, string_table = 8, 0, {}, b''
    while cursor < len(data):
        if cursor + 60 > len(data) or data[cursor+58:cursor+60] != b'`\n':
            raise ValueError('ar成员头无效')
        header = data[cursor:cursor+60]
        try:
            size = int(header[48:58].decode('ascii').strip())
            name = header[:16].decode('ascii').strip()
        except (ValueError, UnicodeError) as error:
            raise ValueError('ar头字段无效') from error
        cursor += 60
        if size < 0 or cursor + size > len(data):
            raise ValueError('ar成员长度逃逸')
        member = data[cursor:cursor+size]
        cursor += size
        if cursor % 2:
            if cursor >= len(data) or data[cursor:cursor+1] != b'\n':
                raise ValueError('ar对齐填充无效')
            cursor += 1
        if name == '//':
            string_table = member
            continue
        if name in ('/', '/SYM64/'):
            continue
        if name.startswith('#1/'):
            count = int(name[3:])
            if count > len(member) or count < 1:
                raise ValueError('BSD长名无效')
            name = member[:count].rstrip(b'\0').decode('utf-8')
            member = member[count:]
        elif re.fullmatch(r'/\d+', name):
            offset = int(name[1:])
            end = string_table.find(b'/\n', offset)
            if offset >= len(string_table) or end < 0:
                raise ValueError('GNU长名无效')
            name = string_table[offset:end].decode('utf-8')
        else:
            name = name.rstrip('/')
        if name in ('__.SYMDEF', '__.SYMDEF SORTED', '__.SYMDEF_64', '__.SYMDEF_64 SORTED'):
            continue
        if not name or '\0' in name:
            raise ValueError('ar空成员名')
        ordinal += 1
        if ordinal > max_members:
            raise ValueError('ar成员数超限')
        names[name] = names.get(name, 0) + 1
        yield {'index': ordinal, 'name': name, 'occurrence': names[name], 'bytes': len(member), 'sha256': digest(member), 'data': member}


def macho_symbols(data):
    """仅接受 arm64 little-endian MH_OBJECT；弱定义/弱引用/common独立保留。"""
    if len(data) < 32 or data[:4] != b'\xcf\xfa\xed\xfe':
        raise ValueError('未知Mach-O格式；拒绝猜测或跳过')
    _, cpu, subtype, filetype, ncmds, sizeofcmds, flags, reserved = struct.unpack_from('<8I', data)
    if cpu != 0x100000c or filetype != 1 or ncmds > 10000 or 32 + sizeofcmds > len(data):
        raise ValueError('需要真实arm64 Mach-O对象或命令长度异常')
    result = {k: set() for k in ('strong', 'weak', 'undefined', 'weakUndefined', 'common')}
    cursor, symtab = 32, None
    for _ in range(ncmds):
        if cursor + 8 > 32 + sizeofcmds:
            raise ValueError('Mach-O命令头越界')
        cmd, size = struct.unpack_from('<2I', data, cursor)
        if size < 8 or cursor + size > 32 + sizeofcmds:
            raise ValueError('Mach-O命令越界')
        if cmd == 2:
            if size != 24 or symtab is not None:
                raise ValueError('Mach-O符号表命令无效')
            symtab = struct.unpack_from('<4I', data, cursor+8)
        cursor += size
    if cursor != 32 + sizeofcmds or symtab is None:
        raise ValueError('Mach-O命令长度或符号表缺失')
    offset, count, stroff, strsize = symtab
    if count > 2000000 or offset + count*16 > len(data) or stroff + strsize > len(data):
        raise ValueError('Mach-O符号表越界')
    for i in range(count):
        index, kind, sect, desc, value = struct.unpack_from('<IBBHQ', data, offset+i*16)
        if kind & 0xe0 or not kind & 1:
            continue
        if index >= strsize:
            raise ValueError('Mach-O字符串索引越界')
        end = data.find(b'\0', stroff+index, stroff+strsize)
        if end < 0:
            raise ValueError('Mach-O符号未终止')
        name = data[stroff+index:end].decode('utf-8')
        typ = kind & 0xe
        if typ == 0:
            bucket = 'common' if value else ('weakUndefined' if desc & 0x40 else 'undefined')
        elif typ in (2, 0xe):
            bucket = 'weak' if desc & 0x80 else 'strong'
        else:
            raise ValueError('未知外部符号类型：' + str(typ))
        result[bucket].add(name)
    return {k: sorted(v) for k, v in result.items()}


def resolve_inputs(stdout, build, max_inputs=2000, max_total=2*1024**3):
    tokens = shlex.split(stdout)
    if len(tokens) > max_inputs:
        raise ValueError('输入数超限')
    root, total, result = build.resolve(strict=True), 0, []
    for token in tokens:
        path = pathlib.Path(token)
        if '\\' in token or '\0' in token or '..' in path.parts:
            raise ValueError('不安全输入路径')
        path = path if path.is_absolute() else root/path
        resolved = path.resolve()
        if not resolved.is_relative_to(root):
            raise ValueError('输入路径逃逸')
        item = {'path': path.relative_to(root).as_posix(), 'realpath': str(resolved), 'symlink': path.is_symlink()}
        if not path.exists() or any(char in token for char in '*?['):
            item['status'] = 'missing-as-of-sw'
        else:
            if not resolved.is_file():
                raise ValueError('输入不是普通文件')
            size = resolved.stat().st_size
            total += size
            if size > MAX_ARCHIVE or total > max_total:
                raise ValueError('输入体积超限')
            item.update(status='present', bytes=size, sha256=file_sha(resolved))
        result.append(item)
    return result


