def focus_paths(build):
    result = {}
    for group, patterns in FOCUS.items():
        result[group] = []
        for pattern in patterns:
            matches = sorted(build.glob(pattern)) if any(c in pattern for c in '*?[') else [build/pattern]
            if not matches:
                result[group].append({'path': pattern, 'status': 'missing-as-of-sw'})
            for path in matches:
                result[group].extend(resolve_inputs(shlex.quote(path.as_posix()), build))
        if sum(len(v) for v in result.values()) > 2000:
            raise ValueError('focus输入数超限')
    return result


def immutable_snapshot(build):
    paths = {build/name for name in ('config_build.mk', 'config_build_lang.mk', 'config_host.mk', 'config_host_lang.mk')}
    paths.update(pathlib.Path(entry['realpath']) for values in focus_paths(build).values() for entry in values if entry['status'] == 'present')
    return {str(p): {'bytes': p.stat().st_size, 'sha256': file_sha(p), 'mtimeNs': p.stat().st_mtime_ns} for p in sorted(paths)}


def objects(path):
    data = path.read_bytes()
    if len(data) > MAX_ARCHIVE:
        raise ValueError('对象体积超限')
    if data.startswith(b'!<arch>\n'):
        yield from archive_members(data)
    else:
        yield {'index': 1, 'occurrence': 1, 'name': path.name, 'bytes': len(data), 'sha256': digest(data), 'data': data}


def scan(inputs, build, evidence):
    focus = focus_paths(build)
    universe, member_rows, defined, refs = set(), [], {}, {}
    focus_inputs = {entry['realpath']: entry for entries in focus.values() for entry in entries if entry['status'] == 'present'}
    unique_inputs = {e['realpath']: e for e in inputs if e['status'] == 'present'}
    unique_inputs.update(focus_inputs)
    if len(unique_inputs) > 2000 or sum(e['bytes'] for e in unique_inputs.values()) > 2*1024**3:
        raise ValueError('完整诊断输入数或体积超限')
    # 首先获取关注对象的完整定义，随后保留所有现存collector输入中对这些符号的引用来源。
    focus_count = 0
    for realpath, entry in focus_inputs.items():
        evidence.check()
        for member in objects(pathlib.Path(realpath)):
            focus_count += 1
            if focus_count > MAX_MEMBERS:
                raise ValueError('focus成员数超限')
            symbols = macho_symbols(member.pop('data'))
            source = {'path': entry['path'], 'memberIndex': member['index'], 'occurrence': member['occurrence'], 'member': member['name']}
            member_rows.append({**source, **member, 'architecture': 'arm64', **symbols})
            for bucket in ('strong', 'weak', 'common'):
                for symbol in symbols[bucket]:
                    universe.add(symbol)
                    defined.setdefault(symbol, []).append({**source, 'kind': bucket})
    count, graph_definitions = 0, {}
    emitted = {entry['realpath'] for entry in inputs}
    for entries in focus.values():
        for entry in entries:
            entry['collectorStatus'] = ('emitted' if entry.get('realpath') in emitted else 'not-emitted-by-collector')
    for entry in inputs:
        evidence.check()
        if entry['status'] != 'present':
            continue
        combined = {k: set() for k in ('strong', 'weak', 'undefined', 'weakUndefined', 'common')}
        member_count = 0
        for member in objects(pathlib.Path(entry['realpath'])):
            count += 1
            member_count += 1
            if count > MAX_MEMBERS:
                raise ValueError('诊断全图成员数超限')
            evidence.check()
            symbols = macho_symbols(member.pop('data'))
            for bucket, values in symbols.items():
                combined[bucket].update(values)
            for bucket in ('strong', 'weak', 'common'):
                for symbol in universe.intersection(symbols[bucket]):
                    graph_definitions.setdefault(symbol, []).append({'path': entry['path'], 'memberIndex': member['index'], 'member': member['name'], 'occurrence': member['occurrence'], 'kind': bucket})
            for bucket in ('undefined', 'weakUndefined'):
                for symbol in universe.intersection(symbols[bucket]):
                    refs.setdefault(symbol, []).append({'path': entry['path'], 'memberIndex': member['index'], 'member': member['name'], 'occurrence': member['occurrence'], 'kind': bucket})
        entry.update(architecture='arm64' if member_count else 'unknown-empty', contentStatus='objects-inspected' if member_count else 'empty-archive',
                     members=member_count, symbols={k: len(v) for k, v in combined.items()})
    overlaps = {s: sources for s, sources in defined.items() if len([v for v in sources if v['kind'] == 'strong']) > 1}
    intersections = {}
    for group in ('nss-parent', 'uno'):
        excluded = {e['path'] for e in focus[group] if e['status'] == 'present' and (group == 'nss-parent' or e['path'].endswith(('libnet_uno.a', 'libunsafe_uno_uno.a')))}
        unique = {s: sources for s, sources in defined.items() if any(v['path'] in excluded for v in sources) and not any(v['path'] not in excluded for v in graph_definitions.get(s, []))}
        intersections[group] = {'scope': '当前SW已存在对象内独有定义；与其余现存collector输入的undefined交集，不能证明final可排除', 'definitions': unique,
                                'consumers': {s: [r for r in refs.get(s, []) if r['path'] not in excluded] for s in unique if any(r['path'] not in excluded for r in refs.get(s, []))}}
    evidence.json('MEMBERS.json', {'referenceUniverseComplete': False, 'focus': focus, 'members': member_rows, 'rawStrongOverlaps': overlaps,
                                   'focusDefinitions': defined, 'focusUndefinedConsumers': refs, 'parentAndUnoIntersections': intersections})
    return focus


def source_snapshot(source, build):
    paths = [(build, 'config_host.mk'), (source, 'cppu/source/uno/lbenv.cxx'), (source, 'cppu/source/uno/lbmap.cxx'), (source, 'desktop/source/lib/init.cxx')]
    nss = 'workdir/UnpackedTarball/nss/nss/'
    paths += [(build, nss + rel) for rel in ('lib/freebl/loader.c', 'lib/freebl/config.mk', 'lib/freebl/Makefile', 'lib/softoken/pkcs11.c')]
    rows = []
    for root, relative in paths:
        path = root/relative
        if not path.is_file():
            rows.append({'root': root.name, 'path': relative, 'status': 'missing-as-of-sw'})
            continue
        if not path.resolve().is_relative_to(root.resolve()) or path.stat().st_size > MAX_FILE:
            raise ValueError('源码采样路径或体积无效')
        text = path.read_text(encoding='utf-8')
        rows.append({'root': root.name, 'path': relative, 'bytes': path.stat().st_size, 'sha256': file_sha(path),
                     'conditions': [{'line': i, 'text': line} for i, line in enumerate(text.splitlines(), 1)
                                    if re.search(r'\b(OS|CPU|DISABLE_DYNLOADING|ENABLE_DOTNET|CPPU_ENV|JAVA|NSS_STATIC|BL_Unload|BL_Cleanup|BL_SetForkState|FREEBL_GetVector|LIBCRUX|slothy|ICU.dat|udata_setCommonData|ucnv_open|HAVE_FEATURE_JAVA)\w*', line)]})
    resources = []
    for pattern in ('workdir/UnpackedTarball/icu/source/data/in/icudt*l.dat', 'workdir/UnpackedTarball/icu/source/data/out/*.dat', 'workdir/UnpackedTarball/icu/source/data/out/tmp/*.dat', 'workdir/CustomTarget/ios/resources/*.dat', 'instdir/Resources/*.dat', 'AppRootResources/ICU.dat'):
        matches = sorted(build.glob(pattern))
        if not matches:
            resources.append({'path': pattern, 'status': 'missing-as-of-sw'})
        for path in matches:
            resources.extend(resolve_inputs(shlex.quote(path.as_posix()), build))
    return {'sources': rows, 'icuResources': resources}


def execute(args, evidence):
    if sys.platform != 'darwin':
        raise ValueError('只允许真实Darwin工具执行；本机回归不代表Apple链接通过')
    import checkpoint
    import run as ci
    receipt = read_json(ROOT/'ci/inspect_run7.json')
    original = validate_receipt(receipt)
    identity = original['identity']
    work, cache = args.work.resolve(), args.cache.resolve(strict=True)
    if str(work) != identity['work'] or str(ROOT.resolve()) != identity['kernelRoot']:
        raise ValueError('拒绝work/kernelRoot路径改变')
    work.mkdir(parents=True, exist_ok=True)
    if checkpoint.cache_key(identity, 'sw') != original['cacheKey']:
        raise ValueError('原SW缓存key不符')
    for entry in receipt['sourceFiles']:
        path = ROOT/entry['path']
        if not path.resolve().is_relative_to(ROOT) or path.is_symlink() or not path.is_file():
            raise ValueError('源码路径无效')
        if entry['path'] not in EXCEPTIONS and (path.stat().st_size != entry['bytes'] or file_sha(path) != entry['sha256']):
            raise ValueError('原源码变化：' + entry['path'])
    # 新manifest由受信restorer逐项校验。再核实其中所有文件与当前物理源码一致。
    manifest = ROOT.parents[1]/'kernel-source.json'
    new_manifest = read_json(manifest)
    expected_paths = {entry['path'] for entry in receipt['sourceFiles']} | {'ci/inspect_link.py', 'ci/test_inspect_link.py', 'ci/inspect_run7.json'}
    actual_paths = [entry['path'] for entry in new_manifest['files']]
    if new_manifest.get('format') != 'office-pdf-ios-source-v1' or new_manifest.get('root') != 'native-kernels/lizhao-office-pdf-ios' or len(actual_paths) != len(set(actual_paths)) or set(actual_paths) != expected_paths:
        raise ValueError('诊断源码manifest文件集合无效')
    for entry in new_manifest['files']:
        path = ROOT/entry['path']
        if not path.resolve().is_relative_to(ROOT) or path.stat().st_size != entry['bytes'] or file_sha(path) != entry['sha256']:
            raise ValueError('诊断源码manifest不符')
    env = clean_make_environment(os.environ)
    env['HOMEBREW_NO_AUTO_UPDATE'] = '1'
    missing = [p for p in ci.PACKAGES if subprocess.run(['brew', 'list', '--versions', p], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL).returncode]
    if missing:
        evidence.command(['brew', 'install', *missing], env=env)
    prefix = evidence.command(['brew', '--prefix'], env=env).strip()
    make_prefix = pathlib.Path(evidence.command(['brew', '--prefix', 'make'], env=env).strip())
    gmake = (make_prefix/'bin/gmake').as_posix()
    env['PATH'] = ':'.join([(make_prefix/'libexec/gnubin').as_posix(), (make_prefix/'bin').as_posix(), *[(pathlib.Path(prefix)/'opt'/p/'bin').as_posix() for p in ('bison', 'flex', 'gettext')]]) + ':' + env['PATH']
    env['MAKE'], env['GNUMAKE'] = gmake, gmake
    pkgconf = pathlib.Path(evidence.command(['brew', '--prefix', 'pkgconf'], env=env).strip())/'bin/pkgconf'
    report = ci.collect_environment(work)
    if report['errors']:
        raise ValueError('真实工具环境采集失败')
    current = ci.build_identity(work, report, gmake, pkgconf, env)
    evidence.json('INSPECTION-IDENTITY.json', {'original': identity, 'current': current, 'newManifestSha256': file_sha(manifest)})
    validate_host(identity, current)
    restored = checkpoint.restore(work, cache, identity, 'final', original['payloadSha256'], original['manifestSha256'], deadline=evidence.deadline)
    evidence.json('CHECKPOINT-RESTORE.json', restored)
    if checkpoint.config_identity(work) != original['config']:
        raise ValueError('恢复后的四配置身份不符')
    builder = ci.load_builder()
    source, build = work/'libreoffice-source', work/'libreoffice-build'
    commit = evidence.command(['git', '-C', source, 'rev-parse', 'HEAD'], env=env).strip()
    if commit != identity['upstreamCommit']:
        raise ValueError('恢复上游COMMIT不符')
    policy = builder.validate_offline_policy(source)
    compat = builder.validate_build_compatibility(source)
    before = immutable_snapshot(build)
    # scratch仅创建新目录，元数据makefile不写入恢复树；无build/allbuild或候选链接。
    with tempfile.TemporaryDirectory(prefix='office-pdf-inspect-') as folder:
        makefile = pathlib.Path(folder)/'collector.mk'
        makefile.write_text(builder.collector_makefile(), encoding='utf-8')
        stdout = evidence.command([gmake, '--no-print-directory', '-s', '-f', makefile, 'office_pdf_static_inputs'], cwd=build, env=env)
        inputs = resolve_inputs(stdout, build)
        focus = scan(inputs, build, evidence)
        snapshot = source_snapshot(source, build)
    if immutable_snapshot(build) != before:
        raise ValueError('metadata采集期间配置或focus原件size/SHA/nsmtime改变')
    if checkpoint.config_identity(work) != original['config']:
        raise ValueError('只读采集改变了四配置')
    evidence.json('INSPECTION.json', {'inspectionComplete': True, 'inspectionOnly': True, 'candidateBuilt': False, 'appleLinkVerified': False,
        'deviceRuntimeVerified': False, 'referenceUniverseComplete': False, 'cacheSaved': False, 'checkpointPhase': 'sw', 'boundary': 'missing-as-of-sw不是完整final输入或链接证明；未选择或删除任何对象',
        'inputs': inputs, 'focus': focus, 'immutableBeforeAndAfter': before, 'configuration': snapshot, 'offlinePolicy': policy, 'buildCompatibility': compat})


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--work', required=True, type=pathlib.Path)
    parser.add_argument('--cache', required=True, type=pathlib.Path)
    parser.add_argument('--evidence', required=True, type=pathlib.Path)
    args = parser.parse_args()
    # 不覆盖其他证据或恢复根；失败RESULT保留独立体积预算。
    args.evidence.mkdir(parents=True, exist_ok=False)
    evidence = Evidence(args.evidence)
    def timed_out(signum, frame):
        raise TimeoutError('只读诊断达到25分钟内部时限')
    if sys.platform == 'darwin':
        signal.signal(signal.SIGALRM, timed_out)
        signal.setitimer(signal.ITIMER_REAL, 25*60)
    try:
        execute(args, evidence)
        evidence.check()
        finish_success(evidence)
    except Exception as error:
        result = {'inspectionComplete': False, 'inspectionOnly': True, 'candidateBuilt': False, 'appleLinkVerified': False,
                  'deviceRuntimeVerified': False, 'referenceUniverseComplete': False, 'errorType': type(error).__name__, 'error': str(error)[:1000]}
        raw = json.dumps(result, ensure_ascii=False).encode('utf-8')
        # 失败状态不冒充成功；完整日志超限时仍留下有界失败回执。
        if (args.evidence/'RESULT.json').is_file():
            (args.evidence/'RESULT.json').unlink()
        with (args.evidence/'RESULT.json').open('xb') as stream:
            stream.write(raw)
        print('只读诊断失败：' + str(error)[:1000], file=sys.stderr)
        return 1
    finally:
        if sys.platform == 'darwin':
            signal.setitimer(signal.ITIMER_REAL, 0)
    return 0


if __name__ == '__main__':
