    office->pClass->setOptionalFeatures(office, LOK_FEATURE_DOCUMENT_PASSWORD | LOK_FEATURE_DOCUMENT_PASSWORD_TO_MODIFY);
    // 固定tag非Android分支识别EnableMacrosExecution=false并设置NEVER_EXECUTE。
    // 本地候选补丁在Kit加载入口强制NEVER_EXECUTE/NO_UPDATE；尚待Apple与恶意样本验证。
    Document document(office->pClass->documentLoadWithOptions(office, inputURL.absoluteString.UTF8String,
        "EnableMacrosExecution=false,MacroSecurityLevel=3"));
    NSDictionary *result;
    if (password.requested.load()) result = failure(@"PASSWORD_REQUIRED", @"DOCUMENT_PASSWORD_REQUIRED");
    else if (!document) result = failure(@"NATIVE_FAILURE", @"KERNEL_DOCUMENT_LOAD_FAILED");
    else if (expired(deadline)) result = failure(@"TIMEOUT", @"KERNEL_DEADLINE");
    else {
        const int expected = [format hasPrefix:@"doc"] ? LOK_DOCTYPE_TEXT : LOK_DOCTYPE_PRESENTATION;
        if (document->pClass->getDocumentType(document.get()) != expected) result = failure(@"TYPE_MISMATCH", @"FORMAT_CONTENT_MISMATCH");
        else {
            document->pClass->initializeForRendering(document.get(), "{}");
            int saved = document->pClass->saveAs(document.get(), outputURL.absoluteString.UTF8String, "pdf", "");
            if (expired(deadline)) result = failure(@"TIMEOUT", @"KERNEL_DEADLINE");
            else if (!saved) result = failure(@"NATIVE_FAILURE", @"KERNEL_SAVE_FAILED");
            else result = @{ @"type": @"success", @"sourceFormat": format, @"engineVersion": @"26.2.6.3", @"released": @YES };
        }
    }
    // callback上下文在解除注册前必须存活；engine/profile继续驻留进程，不透传客户路径。
    document.reset();
    return result;
}
}
const char *OfficePdfKernelProbeJSON(const char *bundlePath) {
    (void)bundlePath;
    return json(@{ @"available": @NO, @"strictOffline": @NO,
        @"supportsHardCancel": @NO, @"testOnly": @(OFFICE_PDF_ACCEPTANCE_ONLY != 0),
        @"acceptanceOnly": @(OFFICE_PDF_ACCEPTANCE_ONLY != 0),
        @"offlinePolicySha256": [NSString stringWithUTF8String:OFFICE_PDF_POLICY_SHA256],
        @"engine": @"libreoffice", @"engineVersion": @"26.2.6.3",
        @"sourceTag": [NSString stringWithUTF8String:kSourceTag],
        @"nativeCode": @"IOS_OFFLINE_POLICY_UNQUALIFIED" });
}
static const char *convertRequestJSON(const char *requestJSON, bool acceptanceOnly) {
    @autoreleasepool {
        std::unique_lock<std::mutex> lease(engineMutex, std::try_to_lock);
        if (!lease.owns_lock()) return json(failure(@"BUSY", @"KERNEL_BUSY"));
        if (!requestJSON || strlen(requestJSON) > 65536) return json(failure(@"INVALID_ARGUMENT", @"KERNEL_REQUEST_INVALID"));
        NSData *data = [NSData dataWithBytes:requestJSON length:strlen(requestJSON)];
        id request = [NSJSONSerialization JSONObjectWithData:data options:0 error:nil];
        if (![request isKindOfClass:NSDictionary.class]) return json(failure(@"INVALID_ARGUMENT", @"KERNEL_REQUEST_INVALID"));
        @try {
            NSMutableDictionary *result = [exportDocument(request) mutableCopy];
            result[@"testOnly"] = @(acceptanceOnly);
            return json(result);
        }
        @catch (NSException *exception) { (void)exception; return json(failure(@"NATIVE_FAILURE", @"KERNEL_OBJC_EXCEPTION")); }
    }
}
const char *OfficePdfKernelConvertJSON(const char *requestJSON) {
    if (!kStrictOfflineQualified) return json(failure(@"ENGINE_UNAVAILABLE", @"IOS_OFFLINE_POLICY_UNQUALIFIED"));
    return convertRequestJSON(requestJSON, false);
}
const char *OfficePdfKernelAcceptanceConvertJSON(const char *requestJSON) {
#if OFFICE_PDF_ACCEPTANCE_ONLY
    // 独立ABI只进入专用验收包；不接受JSON、环境变量或资源清单解除生产门禁。
    return convertRequestJSON(requestJSON, true);
#else
    (void)requestJSON;
    return json(failure(@"ENGINE_UNAVAILABLE", @"KERNEL_ACCEPTANCE_ENTRY_DISABLED"));
#endif
}
